    },
    tabText: { fontSize: 12, fontWeight: "700", color: C.textSub },
    tabTextActive: { color: "#FFFFFF" },

    // Scroll
    scroll: { paddingBottom: 20 },

    // Hero
    heroRow: {
      flexDirection: "row",
      alignItems: "flex-end",
      paddingHorizontal: 20,
      marginBottom: 24,
    },
    heroTitle: {
      fontSize: 30,
      fontWeight: "700",
      color: C.text,
      lineHeight: 36,
      letterSpacing: -0.5,
    },

    // Horizontal scroll
    hScroll: { paddingLeft: 20, paddingRight: 10 },

    // Card container
    card: {
      marginHorizontal: 20,
      marginBottom: 22,
      backgroundColor: C.surface,
