      overflow: "hidden",
    },

    // Empty
    emptyCard: {
      width: CARD_W,
      height: 200,
      borderRadius: 20,
      backgroundColor: C.surface,
      borderWidth: 1,
      borderColor: C.border,
      alignItems: "center",
      justifyContent: "center",
    },
    emptyInCard: {
      padding: 24,
      alignItems: "center",
