  image,
  metadata,
  onReset,
}: CapturePreviewProps) {
  const router = useRouter();
  const { colors: C, isDark } = useTheme();
  const [analyzing, setAnalyzing] = useState(false);
  const [description, setDescription] = useState("");
  const [focused, setFocused] = useState(false);

  const scanAnim = useRef(new Animated.Value(0)).current;
  const pulseAnim = useRef(new Animated.Value(1)).current;
  const fadeAnim = useRef(new Animated.Value(0)).current;

  // Fade in on mount
  useEffect(() => {
    Animated.timing(fadeAnim, {
      toValue: 1,
      duration: 420,
      easing: Easing.out(Easing.quad),
      useNativeDriver: true,
    }).start();
  }, []);

  // Scan line loop while analyzing
  useEffect(() => {
    if (analyzing) {
      Animated.loop(
        Animated.timing(scanAnim, {
          toValue: 1,
          duration: 1800,
          easing: Easing.inOut(Easing.sin),
          useNativeDriver: true,
        }),
      ).start();

      // Pulse the button
      Animated.loop(
        Animated.sequence([
          Animated.timing(pulseAnim, {
            toValue: 0.92,
            duration: 700,
            useNativeDriver: true,
          }),
          Animated.timing(pulseAnim, {
            toValue: 1,
            duration: 700,
            useNativeDriver: true,
          }),
        ]),
      ).start();
    } else {
      scanAnim.stopAnimation();
      scanAnim.setValue(0);
      pulseAnim.stopAnimation();
      pulseAnim.setValue(1);
    }
  }, [analyzing]);

  const { isAuthenticated } = useConvexAuth();
  const runAnalysis = useAction(api.analysis.processAndSaveReport);

  const handleAnalyze = async () => {
    if (!isAuthenticated) {
      Alert.alert("Not Logged In", "Please sign in again to submit reports.");
      return;
    }
    setAnalyzing(true);
    try {
      const base64Image = await FileSystem.readAsStringAsync(image, {
        encoding: FileSystem.EncodingType.Base64,
      });
      const reportId = await runAnalysis({
        image: base64Image,
        description,
        lat: metadata?.lat || 0,
        lng: metadata?.lng || 0,
        locationName: metadata?.location || "Unknown",
      });
      router.push({ pathname: "/results", params: { reportId } });
    } catch (err) {
      console.error("Analysis Error:", err);
      Alert.alert(
        "Upload Failed",
        "Could not process the image. Please try again.",
      );
    } finally {
      setAnalyzing(false);
    }
  };

  const scanTranslate = scanAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [0, 380],
  });

  const canSubmit = description.trim().length > 0 && !analyzing;
  const styles = useMemo(() => createStyles(C), [C]);

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === "ios" ? "padding" : "height"}
      style={{ flex: 1 }}
    >
      <Animated.View style={[styles.root, { opacity: fadeAnim }]}>
        <ScrollView
          contentContainerStyle={styles.scroll}
          showsVerticalScrollIndicator={false}
          keyboardShouldPersistTaps="handled"
        >
          {/* ── TOP NAV ── */}
          <View style={styles.topNav}>
            <TouchableOpacity
              onPress={onReset}
              style={styles.navBackBtn}
              disabled={analyzing}
            >
              <RotateCcw
                color={analyzing ? C.textDim : C.textSub}
                size={15}
                strokeWidth={2.5}
              />
            </TouchableOpacity>

            <View style={styles.navCenter}>
              <View style={styles.navStatusDot} />
              <Text style={styles.navTitle}>Evidence review</Text>
            </View>

            {/* Step breadcrumb */}
            <View style={styles.stepRow}>
              <View style={styles.stepDot}>
                <Text style={styles.stepDotText}>1</Text>
              </View>
              <View style={styles.stepLine} />
              <View style={[styles.stepDot, styles.stepDotActive]}>
                <Text style={[styles.stepDotText, styles.stepDotTextActive]}>
                  2
                </Text>
              </View>
            </View>
          </View>

          {/* ── IMAGE VIEWER ── */}
          <View style={styles.imageCard}>

            <Image
              source={{ uri: image }}
              style={styles.previewImage}
              resizeMode="cover"
            />

            {/* Scan line overlay */}
            {analyzing && (
              <>
                <Animated.View
                  style={[
                    styles.scanLine,
                    { transform: [{ translateY: scanTranslate }] },
                  ]}
                />
                <View style={styles.scanningBanner}>
                  <ActivityIndicator color={C.accent} size="small" />
                  <Text style={styles.scanningText}>Processing image</Text>
                </View>
              </>
            )}

            {/* Crosshair center mark */}
            {!analyzing && (
              <View style={styles.crosshairWrap} pointerEvents="none">
                <View style={styles.crosshairH} />
                <View style={styles.crosshairV} />
                <View style={styles.crosshairDot} />
              </View>
            )}

            {/* Metadata strip — blurred glass at bottom */}
            <BlurView
              intensity={70}
              tint={isDark ? "dark" : "light"}
              style={[
                styles.metaStrip,
                !isDark && { backgroundColor: "rgba(255,255,255,0.75)" },
              ]}
            >
              <View style={styles.metaRow}>
                <View style={styles.metaItem}>
                  <Clock color={C.accent} size={11} strokeWidth={2.5} />
                  <Text
                    style={[
                      styles.metaText,
                      !isDark && { color: C.text },
                    ]}
                  >
                    {metadata?.timestamp ?? "—"}
                  </Text>
                </View>
                <View style={styles.metaDivider} />
                <View style={[styles.metaItem, { flex: 1 }]}>
                  <MapPin color={C.accent} size={11} strokeWidth={2.5} />
                  <Text
                    style={[
                      styles.metaText,
                      !isDark && { color: C.text },
                    ]}
                    numberOfLines={1}
                  >
                    {metadata?.location ?? "Location unavailable"}
                  </Text>
                </View>
              </View>
            </BlurView>
          </View>

          {/* ── DESCRIPTION SECTION ── */}
          <View style={styles.section}>
            {/* Label row */}
            <View style={styles.sectionLabelRow}>

              <Text style={styles.sectionLabel}>Site description</Text>
            </View>

            <View
              style={[
                styles.inputWrapper,
                focused && styles.inputWrapperFocused,
              ]}
            >
              {/* Left accent */}
              <View
                style={[
                  styles.inputAccent,
                  focused && styles.inputAccentActive,
                ]}
              />
              <TextInput
                style={styles.textInput}
                placeholder={
                  "Describe the stagnant water,\ncontainer type, or environment…"
                }
                placeholderTextColor={C.textDim}
                multiline
                numberOfLines={4}
                value={description}
                onChangeText={setDescription}
                editable={!analyzing}
                onFocus={() => setFocused(true)}
                onBlur={() => setFocused(false)}
                textAlignVertical="top"
              />
            </View>

            {/* Character nudge */}
            {description.length === 0 && (
              <View style={styles.nudgeRow}>
                <AlertCircle color={C.textDim} size={11} strokeWidth={2} />
                <Text style={styles.nudgeText}>Required before submission</Text>
              </View>
            )}
          </View>

          {/* ── SUBMIT BUTTON ── */}
          <Animated.View
            style={[styles.submitWrap, { transform: [{ scale: pulseAnim }] }]}
          >
            <Pressable
              style={[styles.submitBtn, !canSubmit && styles.submitBtnDisabled]}
              onPress={handleAnalyze}
              disabled={!canSubmit}
            >
              {analyzing ? (
                <View style={styles.submitInner}>
                  <ActivityIndicator color="#FFFFFF" size="small" />
                  <Text style={styles.submitText}>ANALYZING…</Text>
                </View>
              ) : (
                <View style={styles.submitInner}>
                  <ScanLine
                    color={canSubmit ? "#FFFFFF" : C.textDim}
                    size={16}
                    strokeWidth={2.5}
                    fill={canSubmit ? "#FFFFFF" : C.textDim}
                  />
                  <Text
                    style={[
                      styles.submitText,
                      !canSubmit && styles.submitTextDisabled,
                    ]}
                  >
                    Analyze with AI
                  </Text>
                  <ChevronRight
                    color={canSubmit ? "#FFFFFF" : C.textDim}
                    size={16}
                    strokeWidth={3}
                  />
                </View>
              )}
            </Pressable>
          </Animated.View>

          {/* ── DISCARD LINK ── */}
          <TouchableOpacity
            style={styles.discardBtn}
            onPress={onReset}
            disabled={analyzing}
          >
            <Text
              style={[styles.discardText, analyzing && { color: C.textDim }]}
            >
              Discard & retake
            </Text>
          </TouchableOpacity>

          <View style={{ height: 40 }} />
        </ScrollView>
      </Animated.View>
    </KeyboardAvoidingView>
  );
}

