import { useUser } from "@clerk/clerk-expo";
import * as Haptics from "expo-haptics";
import {
  Flame,
  MessageCircle,
  Send,
  Shield,
  ShieldCheck,
  X,
} from "lucide-react-native";
import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  ActivityIndicator,
  Animated,
  Dimensions,
  Easing,
  FlatList,
  Image,
  KeyboardAvoidingView,
  Modal,
  Platform,
  StyleSheet,
  Text,
  TextInput,
  TouchableOpacity,
  View,
} from "react-native";
import { ThemeColors, useTheme } from "../../../context/ThemeContext";

const { height: SCREEN_HEIGHT } = Dimensions.get("window");

export interface CommentItem {
  id: string;
  reportId: string;
  userName: string;
  userAvatar?: string;
  userRole?: string;
  userBarangay?: string;
  text: string;
  timestamp: number;
}

interface CommunityCommentsModalProps {
  visible: boolean;
  onClose: () => void;
  report: {
    _id: string;
    locationName?: string;
    barangay?: string;
    userName?: string;
    status?: string;
    processedImage?: string;
    imageUri?: string;
    image?: string;
    _creationTime?: number;
  } | null;
  comments: CommentItem[];
  onAddComment: (
    reportId: string,
    text: string,
    profile?: {
      userName?: string;
      userAvatar?: string;
      userRole?: string;
      userBarangay?: string;
    },
  ) => void;
  currentUser?: {
    name?: string;
    _id?: string;
    avatar?: string;
    imageUrl?: string;
    role?: string;
    barangay?: string;
  } | null;
}

const formatCommentTime = (time: number) => {
  const diff = Date.now() - time;
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "Just now";
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
};

const normalizeImageUri = (uri?: string) => {
  if (!uri) return "";
  if (uri.startsWith("data:") || uri.startsWith("http")) return uri;
  return `data:image/jpeg;base64,${uri}`;
};

export default function CommunityCommentsModal({
  visible,
  onClose,
  report,
  comments,
  onAddComment,
  currentUser,
}: CommunityCommentsModalProps) {
  const { colors: C } = useTheme();
  const { user: clerkUser } = useUser();
  const [inputText, setInputText] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const flatListRef = useRef<FlatList>(null);

  const slideAnim = useRef(new Animated.Value(SCREEN_HEIGHT)).current;
  const fadeAnim = useRef(new Animated.Value(0)).current;

  // Resolve current user's real name and profile avatar
  const realName =
    currentUser?.name ||
    clerkUser?.fullName ||
    clerkUser?.firstName ||
    clerkUser?.username ||
    "Citizen";

  const realAvatar =
    clerkUser?.imageUrl ||
    `https://ui-avatars.com/api/?name=${encodeURIComponent(
      realName,
    )}&background=1a2240&color=4F8EF7&bold=true`;

  const realRole = currentUser?.role;
  const realBarangay = currentUser?.barangay;

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 250,
          useNativeDriver: true,
        }),
        Animated.spring(slideAnim, {
          toValue: 0,
          tension: 70,
          friction: 12,
          useNativeDriver: true,
        }),
      ]).start();
    } else {
      Animated.parallel([
        Animated.timing(fadeAnim, {
          toValue: 0,
          duration: 200,
          useNativeDriver: true,
        }),
        Animated.timing(slideAnim, {
          toValue: SCREEN_HEIGHT,
          duration: 250,
          easing: Easing.in(Easing.quad),
          useNativeDriver: true,
        }),
      ]).start();
    }
  }, [visible]);

  const handleSend = () => {
    const trimmed = inputText.trim();
    if (!trimmed || !report?._id || isSubmitting) return;

    try {
      Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
    } catch { }

    setIsSubmitting(true);
    onAddComment(report._id, trimmed, {
      userName: realName,
      userAvatar: realAvatar,
      userRole: realRole,
      userBarangay: realBarangay,
    });
    setInputText("");
    setIsSubmitting(false);

    // Scroll to bottom after adding
    setTimeout(() => {
      flatListRef.current?.scrollToEnd({ animated: true });
    }, 150);
  };

  const isCritical = report?.status === "CRITICAL";
  const statusColor = isCritical ? C.danger : C.safe;
  const imageSource = report
    ? normalizeImageUri(
      report.processedImage || report.imageUri || report.image,
    )
    : "";

  const styles = useMemo(() => createStyles(C), [C]);

  if (!visible) return null;

  return (
    <Modal
      visible={visible}
      transparent
      animationType="none"
      onRequestClose={onClose}
      statusBarTranslucent
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : undefined}
        style={styles.modalOverlay}
      >
        {/* Backdrop */}
        <Animated.View style={[styles.backdrop, { opacity: fadeAnim }]}>
          <TouchableOpacity
            style={StyleSheet.absoluteFillObject}
            activeOpacity={1}
            onPress={onClose}
          />
        </Animated.View>

        {/* Slide-up Container */}
        <Animated.View
          style={[
            styles.sheetContainer,
            { transform: [{ translateY: slideAnim }] },
          ]}
        >
          {/* Grab handle */}
          <View style={styles.handleWrap}>
            <View style={styles.grabHandle} />
          </View>

          {/* Header */}
          <View style={styles.header}>
            {imageSource ? (
              <Image source={{ uri: imageSource }} style={styles.reportThumb} />
            ) : (
              <View style={[styles.reportThumb, styles.placeholderThumb]}>
                <MessageCircle color={C.accent} size={18} />
              </View>
            )}

            <View style={styles.headerInfo}>
              <View style={styles.headerTitleRow}>
                <Text style={styles.headerTitle} numberOfLines={1}>
                  {report?.barangay
                    ? `Brgy. ${report.barangay.replace(/^(Barangay|Brgy\.?)\s*/i, "")}`
                    : report?.locationName || "Surveillance Report"}
                </Text>
                <View
                  style={[
                    styles.statusPill,
                    {
                      backgroundColor: statusColor + "18",
                      borderColor: statusColor + "40",
                    },
                  ]}
                >
                  {isCritical ? (
                    <Flame size={9} color={statusColor} />
                  ) : (
                    <ShieldCheck size={9} color={statusColor} />
                  )}
                  <Text style={[styles.statusText, { color: statusColor }]}>
                    {report?.status || "REPORT"}
                  </Text>
                </View>
              </View>
              <Text style={styles.headerSub}>
                {comments.length}{" "}
                {comments.length === 1 ? "Comment" : "Comments"} • Community
                Updates
              </Text>
            </View>

            <TouchableOpacity
              onPress={onClose}
              style={styles.closeBtn}
              activeOpacity={0.7}
            >
              <X color={C.text} size={16} strokeWidth={2.5} />
            </TouchableOpacity>
          </View>

          <View style={styles.divider} />

          {/* Comments List */}
          <FlatList
            ref={flatListRef}
            data={comments}
            keyExtractor={(item) => item.id}
            contentContainerStyle={styles.commentsList}
            showsVerticalScrollIndicator={false}
            ListEmptyComponent={
              <View style={styles.emptyState}>
                <View style={styles.emptyIconBg}>
                  <MessageCircle color={C.accent} size={28} strokeWidth={1.8} />
                </View>
                <Text style={styles.emptyTitle}>No Comments Yet</Text>
                <Text style={styles.emptySub}>
                  Be the first to share an observation, treatment note, or
                  helpful tip for this location.
                </Text>
              </View>
            }
            renderItem={({ item }) => {
              const avatar =
                item.userAvatar ||
                `https://ui-avatars.com/api/?name=${encodeURIComponent(
                  item.userName || "User",
                )}&background=1a2240&color=4F8EF7&bold=true`;

              const isTanodOfficer = item.userRole === "tanod";

              return (
                <View style={styles.commentRow}>
                  <Image
                    source={{ uri: avatar }}
                    style={styles.commentAvatar}
                  />
                  <View style={styles.commentBubble}>
                    <View style={styles.commentMetaRow}>
                      <View style={styles.commentAuthorRow}>
                        <Text style={styles.commentAuthor}>
                          {item.userName || "Citizen"}
                        </Text>
                        {isTanodOfficer && (
                          <View style={styles.tanodBadge}>
                            <Shield size={8} color={C.accent} />
                            <Text style={styles.tanodBadgeText}>TANOD</Text>
                          </View>
                        )}
                        {item.userBarangay && (
                          <Text style={styles.commentBarangayText}>
                            • Brgy.{" "}
                            {item.userBarangay.replace(
                              /^(Barangay|Brgy\.?)\s*/i,
