              onPress={handleSend}
              disabled={inputText.trim().length === 0 || isSubmitting}
              activeOpacity={0.75}
            >
              {isSubmitting ? (
                <ActivityIndicator size="small" color="#FFFFFF" />
              ) : (
                <Send
                  size={15}
                  color={
                    inputText.trim().length > 0 ? "#FFFFFF" : C.textDim
                  }
                  strokeWidth={2.5}
                />
              )}
            </TouchableOpacity>
          </View>
        </Animated.View>
      </KeyboardAvoidingView>
    </Modal>
  );
}

