            >
              <X color={C.text} size={16} strokeWidth={2.5} />
            </TouchableOpacity>
          </View>

          <View style={styles.divider} />

          {/* Share Options */}
          <View style={styles.optionsList}>
            {/* Option 1: Full Report with AI Details */}
