import React, { useEffect, useMemo, useRef } from "react";
import { Animated, Easing, StyleSheet, Text, View } from "react-native";
import { ThemeColors, useTheme } from "../../../context/ThemeContext";

interface StatsProps {
  total: number;
  resolved: number;
  active: number;
  pending: number;
}

// ─── Animated count-up number ─────────────────────────────────────────────────
const CountUp = ({
  value,
  color,
  size = 22,
}: {
  value: number;
  color: string;
  size?: number;
}) => {
  const anim = useRef(new Animated.Value(0)).current;
  const displayed = useRef(0);
  const [display, setDisplay] = React.useState(0);

  useEffect(() => {
    Animated.timing(anim, {
      toValue: value,
      duration: 900,
      easing: Easing.out(Easing.cubic),
      useNativeDriver: false,
    }).start();

    const listener = anim.addListener(({ value: v }) => {
      const rounded = Math.round(v);
      if (rounded !== displayed.current) {
        displayed.current = rounded;
        setDisplay(rounded);
      }
    });
    return () => anim.removeListener(listener);
  }, [value]);

  return (
    <Text
      style={{ fontSize: size, fontWeight: "700", color, letterSpacing: -0.5 }}
    >
      {display}
    </Text>
  );
};

// ─── Single stat cell ─────────────────────────────────────────────────────────
const StatCell = ({
  value,
  label,
  color,
  glowColor,
  textColor,
}: {
  value: number;
  label: string;
  color: string;
  glowColor: string;
  textColor: string;
}) => (
  <View
    style={[
      cell.wrap,
      { backgroundColor: glowColor },
    ]}
  >
    <CountUp value={value} color={color} size={24} />
    <Text style={[cell.label, { color: textColor }]}>{label}</Text>
  </View>
);

const cell = StyleSheet.create({
  wrap: {
    flex: 1,
    alignItems: "center",
    paddingVertical: 16,
    borderRadius: 12,
    position: "relative",
    overflow: "hidden",
  },
  label: {
    fontSize: 11,
    fontWeight: "700",
    letterSpacing: 0.3,
    marginTop: 5,
    textTransform: "none",
  },
});

// ─── Main card ────────────────────────────────────────────────────────────────
export default function ReportStatsCard({
  total,
  resolved,
  active,
  pending,
}: StatsProps) {
  const { colors: C } = useTheme();

  // Fade + slide in on mount
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const slideAnim = useRef(new Animated.Value(10)).current;

  useEffect(() => {
    Animated.parallel([
      Animated.timing(fadeAnim, {
        toValue: 1,
        duration: 420,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      }),
      Animated.timing(slideAnim, {
        toValue: 0,
        duration: 420,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      }),
    ]).start();
  }, []);

  const styles = useMemo(() => createStyles(C), [C]);

  return (
    <Animated.View
      style={[
        styles.card,
        { opacity: fadeAnim, transform: [{ translateY: slideAnim }] },
      ]}
    >
      {/* ── Header row ── */}
      <View style={styles.headerRow}>
        <View style={styles.headerLeft}>

          <Text style={styles.sectionLabel}>Your activity</Text>
        </View>
      </View>

      {/* ── Total ── */}
      <View style={styles.totalRow}>
        <CountUp value={total} color={C.text} size={40} />
        <View style={styles.totalMeta}>
          <Text style={styles.totalLabel}>Total reports</Text>

        </View>
      </View>

      {/* ── Divider ── */}
      <View style={styles.hdivider} />

      {/* ── Stat cells ── */}
      <View style={styles.cellRow}>
        <StatCell
          value={resolved}
          label="Resolved"
          color={C.safe}
          glowColor={C.surfaceRaised}
          textColor={C.textSub}
        />
        <StatCell
          value={active}
          label="Active"
          color={C.danger}
          glowColor={C.surfaceRaised}
          textColor={C.textSub}
        />
        <StatCell
          value={pending}
          label="Pending"
          color={C.warn}
          glowColor={C.surfaceRaised}
          textColor={C.textSub}
        />
      </View>
    </Animated.View>
  );
}

